insert into public.people (id, email, full_name, title, department, office, phone_ext, orcid, bio, joined_year, status) values
  ('b1ebc457-5efe-5818-adae-223a9a03d66a', 'a.raza@northfield.edu', 'Dr. Amina Raza', 'Associate Professor', 'Computer Science', 'Block A · Room 146', 'Ext. 4131', '0000-0001-1490-1919', 'Amina leads the language technology track of the AI Lab. Her research makes large language models useful for low-resource languages, with recent projects on Urdu speech recognition and clinical text summarization for regional hospitals. She teaches Machine Learning and Advanced NLP and supervises six PhD students.', 2021, 'active'),
  ('9070b85e-a8ab-545e-892e-11f30c41172c', 'd.okafor@northfield.edu', 'Dr. Daniel Okafor', 'Professor', 'Computer Science', 'Block B · Room 200', 'Ext. 4860', '0000-0002-9286-8634', 'Daniel works on reinforcement learning and trustworthy AI, with applied projects in hospital records. At Northfield, Daniel teaches Machine Learning and supervises student research.', 2015, 'active'),
  ('9f4acd37-6eb7-5cc9-8dc2-8a7e5266e6e5', 'm.chen@northfield.edu', 'Dr. Mei Lin Chen', 'Assistant Professor', 'Electrical Engineering', 'Block C · Room 341', 'Ext. 4126', '0000-0002-7303-6350', 'Mei works on remote sensing and visual recognition, with applied projects in agriculture. At Northfield, Mei teaches Image Processing and supervises student research.', 2022, 'active'),
  ('4b152fc6-bbb8-52dc-a2c8-4f0b2fcafd73', 'h.qureshi@northfield.edu', 'Hassan Qureshi', 'Lecturer', 'Computer Science', 'Block D · Room 181', 'Ext. 4298', '0000-0002-5106-8290', 'Hassan works on speech and language technology and large language models, with applied projects in public services. At Northfield, Hassan teaches Machine Learning and supervises student research.', 2023, 'active'),
  ('b8dc8425-8536-59e3-9396-f8a59caccd40', 's.marquez@northfield.edu', 'Dr. Sofia Marquez', 'Associate Professor', 'Statistics', 'Block E · Room 234', 'Ext. 4399', '0000-0002-1900-7937', 'Sofia works on Bayesian modelling and forecasting, with applied projects in energy systems. At Northfield, Sofia teaches Probability and supervises student research.', 2018, 'active'),
  ('90f1eab3-eb43-50f0-b71b-6fde27ea496e', 'a.mehta@northfield.edu', 'Dr. Arjun Mehta', 'Research Fellow', 'Computer Science', 'Block A · Room 149', 'Ext. 4280', '0000-0001-7075-3203', 'Arjun works on reinforcement learning and trustworthy AI, with applied projects in low-resource languages. At Northfield, Arjun teaches Algorithms and supervises student research.', 2024, 'active'),
  ('ee5b40ed-152a-5556-bdd1-3fb6e8a211fd', 'f.noor@northfield.edu', 'Fatima Noor', 'Senior Lecturer', 'Education', 'Block B · Room 333', 'Ext. 4462', '0000-0003-3205-6624', 'Fatima works on curriculum reform and inclusive teaching, with applied projects in teacher training. At Northfield, Fatima teaches Pedagogy and supervises student research.', 2017, 'active'),
  ('cf793e01-e1e9-5ab4-8ca2-99958773bb92', 'l.berg@northfield.edu', 'Dr. Lukas Berg', 'Professor', 'Mechatronics', 'Block C · Room 222', 'Ext. 4384', '0000-0001-2162-7864', 'Lukas works on visual recognition and medical image analysis, with applied projects in robotics. At Northfield, Lukas teaches Image Processing and supervises student research.', 2013, 'active'),
  ('193460d8-ff85-5837-9f6c-f0c037d5f965', 'z.siddiqui@northfield.edu', 'Zara Siddiqui', 'PhD Researcher', 'Computer Science', 'Block D · Room 294', 'Ext. 4340', '0000-0001-3220-7363', null, 2024, 'active'),
  ('225cf4a3-9366-55ce-b089-32a2c1c3a8b8', 'o.haddad@northfield.edu', 'Dr. Omar Haddad', 'Assistant Professor', 'Data Science', 'Block E · Room 296', 'Ext. 4189', '0000-0002-3601-2321', 'Omar works on forecasting and causal inference, with applied projects in public health. At Northfield, Omar teaches Probability and supervises student research.', 2022, 'active'),
  ('ae419635-5e7c-5037-98a2-32176b33275b', 'p.nair@northfield.edu', 'Dr. Priya Nair', 'Associate Professor', 'Education', 'Block A · Room 139', 'Ext. 4851', '0000-0002-6081-5111', 'Priya works on curriculum reform and inclusive teaching, with applied projects in teacher training. At Northfield, Priya teaches Pedagogy and supervises student research.', 2019, 'active'),
  ('8c4bb43c-5fe4-5eea-9752-9100383810ba', 'e.brooks@northfield.edu', 'Ethan Brooks', 'Lecturer', 'Mathematics', 'Block B · Room 171', 'Ext. 4701', '0000-0003-9051-4655', null, 2024, 'active'),
  ('60949313-2731-51ea-b189-20f4b1ae06f0', 'a.khan@northfield.edu', 'Dr. Ayesha Khan', 'Assistant Professor', 'Biomedical Engineering', 'Block C · Room 246', 'Ext. 4141', '0000-0002-4778-1662', 'Ayesha works on medical image analysis and 3D perception, with applied projects in robotics. At Northfield, Ayesha teaches Robotics and supervises student research.', 2023, 'active'),
  ('d72c48ef-65a0-5f0a-b4e9-fbe33dcbd87a', 'k.watanabe@northfield.edu', 'Kenji Watanabe', 'Visiting Researcher', 'Computer Science', 'Block D · Room 179', 'Ext. 4170', '0000-0003-6919-6875', 'Kenji works on reinforcement learning and trustworthy AI, with applied projects in software engineering. At Northfield, Kenji teaches Python Programming and supervises student research.', 2026, 'invited'),
  ('29a775ff-a64d-5589-834f-6f9ec4378987', 'n.said@northfield.edu', 'Noura Said', 'Lecturer', 'Education', 'Block E · Room 385', 'Ext. 4864', '0000-0003-8747-9925', 'Noura works on curriculum reform and inclusive teaching, with applied projects in online programmes. At Northfield, Noura teaches Research Methods and supervises student research.', 2025, 'invited')
