  ('90948c68-e89c-55c4-885e-e198ab34eae1', 'ai-lab', 'Artificial Intelligence Lab', 'AI', 'Language models, reinforcement learning and trustworthy AI, with applied work in health and low-resource languages.', 'lagoon', '9070b85e-a8ab-545e-892e-11f30c41172c', 2019),
